use std::{fs, io};
use crate::{Difference, OutputKey, Profile, Value, key_parts, ordered_keys};
use crate::schema::Kind;

pub const MASK: &str = "********";
pub fn string_notation(text: &str) -> String {
    let mut result = String::from("\"");
    for c in text.chars() {
        match c { '\\' => result.push_str("\\\\"), '"' => result.push_str("\\\""), '\n' => result.push_str("\\n"), '\t' => result.push_str("\\t"), _ => result.push(c) }
    }
    result.push('"'); result
}
pub fn value_notation(kind: Kind, item: Kind, value: &Value) -> String {
    match value {
        Value::List(items) => format!("[{}]", items.iter().map(|v| value_notation(item, Kind::String, v)).collect::<Vec<_>>().join(", ")),
        Value::Text(text) if kind == Kind::String => string_notation(text),
        Value::Text(text) => text.clone(), Value::Integer(n) => n.to_string(), Value::Boolean(b) => b.to_string(),
    }
}
pub fn shown(output: &OutputKey) -> &str { if output.secret { MASK } else { &output.notation } }

fn normalized(profile: &Profile) -> Vec<String> {
    let mut lines = vec![format!("profile {}", profile.name)];
    let mut current = String::new();
    for key in ordered_keys(&profile.outputs) {
        let (section, name) = key_parts(&key);
        if section != current { lines.push(format!("[{section}]")); current = section.into(); }
        lines.push(format!("{name} = {}", shown(&profile.outputs[&key])));
    }
    lines
}
fn diagnostics(profile: &Profile) -> Vec<String> {
    let mut lines = vec![format!("profile {} errors {} warnings {}", profile.name, profile.errors, profile.warnings)];
    lines.extend(profile.diagnostics.iter().map(|d| format!("{} {} {}", d.origin.text(), d.code, d.message)));
    lines
}
fn report(profile: &Profile) -> Vec<String> {
    let mut lines = vec![format!("profile {}", profile.name), "includes".into()];
    lines.extend(profile.tree.iter().map(|(depth, text)| format!("{}{text}", "  ".repeat(depth + 1))));
    lines.push("overridden".into());
    if profile.overridden.is_empty() { lines.push("  (none)".into()); }
    for (key, history) in &profile.overridden {
        lines.push(format!("  {key}: {}", history.iter().map(|o| o.text()).collect::<Vec<_>>().join(" -> ")));
    }
    lines.push(format!("keys {} documents {} manifest {} defaults {}", profile.outputs.len(), profile.document_keys, profile.manifest_keys, profile.default_keys));
    lines.push(format!("dropped {}", profile.dropped));
    lines.push(format!("errors {} warnings {}", profile.errors, profile.warnings));
    lines
}
fn difference(diff: &Difference) -> Vec<String> {
    let mut lines = vec![format!("diff {} -> {}: {} added, {} removed, {} changed", diff.first, diff.second, diff.added, diff.removed, diff.changed)];
    for (key, before, after) in &diff.entries {
        lines.push(match (before, after) {
            (None, Some(value)) => format!("+ {key} = {value}"), (Some(value), None) => format!("- {key} = {value}"),
            (Some(a), Some(b)) => format!("~ {key}: {a} -> {b}"), _ => unreachable!(),
        });
    }
    lines
}
fn write(name: &str, blocks: Vec<Vec<String>>) -> io::Result<()> {
    let text = blocks.into_iter().map(|lines| lines.join("\n")).collect::<Vec<_>>().join("\n\n") + "\n";
    fs::write(format!("output/{name}.txt"), text)
}
pub fn write_outputs(profiles: &[Profile], diffs: &[Difference]) -> io::Result<()> {
    fs::create_dir_all("output")?;
    write("normalized", profiles.iter().map(normalized).collect())?;
    write("diagnostics", profiles.iter().map(diagnostics).collect())?;
    write("report", profiles.iter().map(report).collect())?;
    write("diff", diffs.iter().map(difference).collect())
}

use std::collections::BTreeMap;
use crate::{Diagnostic, Origin};
use crate::lexer::logical_lines;

pub fn is_name(text: &str) -> bool {
    let bytes = text.as_bytes();
    !bytes.is_empty() && bytes[0].is_ascii_lowercase()
        && bytes[1..].iter().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'_')
}

pub fn is_section(text: &str) -> bool { text.split('.').all(is_name) }

#[derive(Clone, Copy)]
pub enum StatementKind { Assign, Append, Unset, Inherit, Include }

#[derive(Clone)]
pub struct Statement {
    pub kind: StatementKind,
    pub line: usize,
    pub target: String,
    pub value: String,
}

#[derive(Clone)]
pub struct Document { pub statements: Vec<Statement>, pub diagnostics: Vec<Diagnostic> }

fn trim(segments: &mut [String]) {
    segments[0] = segments[0].trim_start_matches(' ').into();
    let last = segments.len() - 1;
    segments[last] = segments[last].trim_end_matches(' ').into();
}

pub fn parse_document(name: &str, source: &str) -> Document {
    let mut document = Document { statements: Vec::new(), diagnostics: Vec::new() };
    let mut diagnostics = Vec::new();
    let mut section: Option<String> = None;
    let mut base: Option<String> = None;
    let mut assigned = BTreeMap::new();
    for line in logical_lines(source) {
        let origin = Origin::new(name, line.number);
        let mut report = |code, message: String| diagnostics.push(Diagnostic { origin: origin.clone(), code, message });
        if let Some((code, message)) = line.error { report(code, message); continue; }
        let mut segments = line.segments;
        trim(&mut segments);
        let first = &segments[0];
        if segments.len() == 1 && first.is_empty() { continue; }
        if first.starts_with('[') {
            let header = if segments.len() == 1 && first.ends_with(']') {
                let inside = &first[1..first.len() - 1];
                let (child, parent) = match inside.split_once(':') {
                    Some((child, parent)) => (child.trim_matches(' '), Some(parent.trim_matches(' '))),
                    None => (inside.trim_matches(' '), None),
                };
                let relative = child.starts_with('.') && is_section(&child[1..]);
                if (!relative && !is_section(child)) || parent.is_some_and(|p| !is_section(p)) {
                    Err("invalid section header")
                } else if relative && base.is_none() {
                    Err("relative section without base")
                } else {
                    Ok((if relative { format!("{}{child}", base.as_ref().unwrap()) } else { child.into() }, relative, parent))
                }
            } else { Err("invalid section header") };
            match header {
                Err(message) => { report("E_SECTION", message.into()); section = None; }
                Ok((child, relative, parent)) => {
                    if !relative { base = Some(child.clone()); }
                    section = Some(child.clone());
                    if let Some(parent) = parent {
                        document.statements.push(Statement { kind: StatementKind::Inherit, line: line.number, target: child, value: parent.into() });
                    }
                }
            }
        } else if first.starts_with('@') {
            let words: Vec<&str> = first.split(' ').filter(|s| !s.is_empty()).collect();
            if segments.len() != 1 || words.len() != 2 || !["@include", "@unset"].contains(&words[0]) || !is_name(words[1]) {
                report("E_SYNTAX", "invalid directive".into());
            } else if words[0] == "@include" {
                document.statements.push(Statement { kind: StatementKind::Include, line: line.number, target: words[1].into(), value: String::new() });
            } else if let Some(section) = &section {
                document.statements.push(Statement { kind: StatementKind::Unset, line: line.number, target: format!("{section}.{}", words[1]), value: String::new() });
            } else { report("E_NO_SECTION", "no current section".into()); }
        } else {
            if !segments.iter().step_by(2).any(|s| s.contains('=')) { report("E_SYNTAX", "invalid line".into()); continue; }
            let Some((key, rest)) = first.split_once('=') else { report("E_SYNTAX", "invalid key".into()); continue; };
            let mut key = key.trim_matches(' ');
            let append = key.ends_with('+');
            if append { key = key[..key.len() - 1].trim_end_matches(' '); }
            if !is_name(key) { report("E_SYNTAX", "invalid key".into()); continue; }
            let mut value_segments = vec![rest.to_owned()];
            value_segments.extend_from_slice(&segments[1..]);
            trim(&mut value_segments);
            let value = match value_segments.as_slice() {
                [value] => value.clone(),
                [before, value, after] if before.is_empty() && after.is_empty() => value.clone(),
                _ => { report("E_SYNTAX", "invalid value".into()); continue; }
            };
            let Some(section) = &section else { report("E_NO_SECTION", "no current section".into()); continue; };
            let target = format!("{section}.{key}");
            if !append {
                if let Some(previous) = assigned.insert(target.clone(), line.number) {
                    report("W_DUPLICATE", format!("{target} already set at line {previous}"));
                }
            }
            document.statements.push(Statement { kind: if append { StatementKind::Append } else { StatementKind::Assign }, line: line.number, target, value });
        }
    }
    document.diagnostics = diagnostics;
    document
}

use std::collections::{BTreeMap, BTreeSet};
use crate::{Definition, Diagnostic, key_parts, ordered_keys};
use crate::ini_parser::is_section;
use crate::lexer::LITERAL_DOLLAR;

pub struct Expansion { pub results: BTreeMap<String, Option<String>>, pub diagnostics: Vec<Diagnostic> }

struct Expander<'a> {
    definitions: &'a BTreeMap<String, Definition>,
    expansion: Expansion,
    active: Vec<String>,
    cycle_keys: BTreeSet<String>,
}

impl Expander<'_> {
    fn report(&mut self, key: &str, code: &'static str, message: String) {
        self.expansion.diagnostics.push(Diagnostic { origin: self.definitions[key].origin.clone(), code, message });
    }
    fn expand(&mut self, key: &str) -> Option<String> {
        if let Some(result) = self.expansion.results.get(key) { return result.clone(); }
        self.active.push(key.into());
        let result = self.evaluate(key);
        self.active.pop();
        self.expansion.results.insert(key.into(), result.clone());
        result
    }
    fn evaluate(&mut self, key: &str) -> Option<String> {
        let value = self.definitions[key].value.clone();
        let bytes = value.as_bytes();
        let mut result = String::new();
        let mut position = 0;
        while position < bytes.len() {
            if bytes[position] != b'$' || bytes.get(position + 1) != Some(&b'{') {
                result.push(if bytes[position] == LITERAL_DOLLAR { '$' } else { bytes[position] as char });
                position += 1;
                continue;
            }
            let close = value[position + 2..].find('}').map(|p| p + position + 2);
            let Some(close) = close.filter(|&p| is_section(&value[position + 2..p])) else {
                self.report(key, "E_BAD_REF", format!("{key}: invalid reference")); return None;
            };
            let reference = &value[position + 2..close];
            let target = if reference.contains('.') { reference.into() } else { format!("{}.{reference}", key_parts(key).0) };
            if !self.definitions.contains_key(&target) {
                self.report(key, "E_UNDEFINED", format!("{key}: undefined reference {target}")); return None;
            }
            let expanded = if let Some(start) = self.active.iter().position(|s| s == &target) {
                let mut path = self.active[start..].to_vec();
                path.push(target.clone());
                self.report(&target, "E_CYCLE", format!("interpolation cycle {}", path.join(" -> ")));
                self.cycle_keys.extend(path);
                None
            } else { self.expand(&target) };
            match expanded {
                Some(text) => result.push_str(&text),
                None => {
                    if !self.cycle_keys.contains(key) { self.report(key, "E_DEPENDENCY", format!("{key}: depends on failed key {target}")); }
                    return None;
                }
            }
            position = close + 1;
        }
        Some(result)
    }
}

pub fn expand(definitions: &BTreeMap<String, Definition>) -> Expansion {
    let mut expander = Expander {
        definitions, expansion: Expansion { results: BTreeMap::new(), diagnostics: Vec::new() },
        active: Vec::new(), cycle_keys: BTreeSet::new(),
    };
    for key in ordered_keys(definitions) { expander.expand(&key); }
    expander.expansion
}

pub const LITERAL_DOLLAR: u8 = 1;

pub struct LogicalLine {
    pub number: usize,
    pub segments: Vec<String>,
    pub error: Option<(&'static str, String)>,
}

pub fn logical_lines(source: &str) -> Vec<LogicalLine> {
    let physical: Vec<&[u8]> = source.lines().map(str::as_bytes).collect();
    let mut lines = Vec::new();
    let mut index = 0;
    while index < physical.len() {
        let mut line = LogicalLine { number: index + 1, segments: Vec::new(), error: None };
        let mut source = physical[index];
        index += 1;
        let mut position = 0;
        let mut quoted = false;
        let mut current = String::new();
        while position < source.len() {
            let byte = source[position];
            if byte == b'\\' && position + 1 == source.len() {
                source = physical[index];
                index += 1;
                position = source.iter().position(|&c| c != b' ').unwrap_or(source.len());
            } else if quoted && byte == b'\\' {
                let follower = source[position + 1];
                let decoded = match follower {
                    b'\\' | b'"' => Some(follower),
                    b'n' => Some(b'\n'), b't' => Some(b'\t'), b'$' => Some(LITERAL_DOLLAR),
                    _ => None,
                };
                if let Some(c) = decoded {
                    current.push(c as char);
                } else if line.error.is_none() {
                    line.error = Some(("E_ESCAPE", format!("invalid escape sequence \\{}", follower as char)));
                }
                position += 2;
            } else if byte == b'"' {
                line.segments.push(std::mem::take(&mut current));
                quoted = !quoted;
                position += 1;
            } else if !quoted && (byte == b';' || byte == b'#') {
                break;
            } else {
                current.push(byte as char);
                position += 1;
            }
        }
        if quoted && line.error.is_none() {
            line.error = Some(("E_UNTERMINATED", "unterminated string".into()));
        }
        line.segments.push(current);
        lines.push(line);
    }
    lines
}

